export function editorialQuestion(){return {stemText:'Bir gezi için aynı sayıda koltuk sunan iki servis teklifi tabloda verilmiştir. Birinci teklif iki eşit araçla 120 kişiyi taşırken ikinci teklif dört araçla aynı grubu taşır. Birinci teklifin toplam bedeli 480 TL, ikinci teklifin araç başına bedeli 110 TL ise hangi teklif seçilmeli ve toplam kaç TL daha az ödenmelidir?',options:[{label:'A',text:'İkinci teklif; 40 TL'},{label:'B',text:'Birinci teklif; 40 TL'},{label:'C',text:'İkinci teklif; 370 TL'},{label:'D',text:'İkinci teklif; 260 TL'}],correctAnswer:'A',solutionText:'İkinci teklifin toplam bedeli 4 × 110 = 440 TL olur. İki teklif aynı grubu taşıdığından toplam bedeller karşılaştırılır: 480 − 440 = 40 TL. İkinci teklif seçilmelidir. Doğru seçenek A) İkinci teklif; 40 TL.',difficultyLevel:4,editorial:{version:1,cognitiveDemand:'ANALYZE',skillTarget:'Aynı ihtiyacı karşılayan farklı tekliflerin toplam bedelini karşılaştırma.',reasoningSteps:['İkinci teklifte araç başına verilen bedeli toplam araç sayısıyla ilişkilendirir.','İki teklifin toplam bedellerini aynı taşıma ihtiyacı için karşılaştırır.'],distractors:[{label:'B',misconception:'Fiyat farkını hesaplayıp ucuz teklifin yönünü ters seçme.',whyIncorrect:'40 TL fark doğru olsa da birinci teklifin bedeli 480 TL, ikinci teklifin bedeli 440 TL olduğu için birinci teklif daha pahalıdır.'},{label:'C',misconception:'Toplam bedel ile araç başına bedeli doğrudan karşılaştırma.',whyIncorrect:'480 TL toplam bedelden 110 TL araç başına bedeli çıkarmak eşit birimleri karşılaştırmaz; dört araç için 440 TL ödenir.'},{label:'D',misconception:'İkinci teklifin dört araç yerine iki aracının bedelini hesaplama.',whyIncorrect:'İkinci teklifte dört araç gerektiğinden 220 TL hesabı eksik kalır; toplam bedel 440 TL olmalıdır.'}],originalityDesign:'Toplam fiyat ile birim fiyatı aynı ölçekte değerlendirme ve karşılaştırma yönünü gerekçelendirme birlikte ölçülür.',visual:{kind:'TABLE',title:'Servis teklifleri',unit:'TL',columns:['Teklif','Araç sayısı','Ücret türü','Bedel'],rows:[['Birinci','2','Toplam','480'],['İkinci','4','Araç başına','110']],categories:[],values:[],readingPurpose:'Araç sayısı ile fiyatın toplam mı birim mi olduğunu birlikte okuyarak adil fiyat karşılaştırması yapma.'}}};}
